style.css:
@-moz-document domain("aistudio.google.com") {
/* --- BIẾN MÀU & PHÔNG CHỮ CHÍNH --- */
  :root {
    --bg-primary: #121212; /* Nền chính tối hơn */
    --bg-secondary: #1E1E1E; /* Nền phụ cho các panel */
    --bg-tertiary: #2a2a2a; /* Nền cho các thành phần con */
    --accent-primary: #8ab4f8; /* Màu nhấn chính (xanh lam) */
    --accent-secondary: #4a6da7; /* Màu nhấn phụ, tối hơn */
    --text-primary: #e8eaed; /* Màu chữ chính */
    --text-secondary: #9aa0a6; /* Màu chữ phụ */
    --border-color: #3c4043; /* Màu viền */
    --shadow-color: rgba(138, 180, 248, 0.2); /* Màu bóng mờ */
    --font-main: 'Google Sans Text', 'Inter', sans-serif;
  }

  /* --- THIẾT LẬP TOÀN CỤC --- */
  body, .dark-theme {
    background-color: var(--bg-primary) !important;
    font-family: var(--font-main) !important;
    color: var(--text-primary) !important;
  }

  /* --- THANH ĐIỀU HƯỚNG BÊN TRÁI --- */
  ms-navbar .layout-navbar {
    background-color: var(--bg-secondary) !important;
    border-right: 1px solid var(--border-color) !important;
  }

  ms-navbar .nav-item {
    border-radius: 8px !important;
    transition: background-color 0.3s ease, color 0.3s ease !important;
  }

  ms-navbar .nav-item:hover {
    background-color: var(--bg-tertiary) !important;
  }

  ms-navbar .nav-item.active, ms-navbar .nav-item.active-override {
    background-color: var(--accent-secondary) !important;
    color: white !important;
  }
  
  ms-navbar .nav-item.active .material-symbols-outlined,
  ms-navbar .nav-item.active-override .material-symbols-outlined {
    color: white !important;
  }

  /* --- HEADER CHÍNH --- */
  ms-header-root .header-container {
    background-color: var(--bg-primary) !important;
    border-bottom: 1px solid var(--border-color) !important;
  }

  ms-model-selector-collapsible .mat-mdc-form-field-flex {
    background-color: var(--bg-secondary) !important;
  }
  
  /* --- KHU VỰC CHAT CHÍNH --- */
  .chunk-editor-main, .v3-bg-enabled {
    background-color: var(--bg-primary) !important;
    border-radius: 12px !important;
  }

  /* Giao diện trang bắt đầu */
  ms-zero-state .promo-card {
    background-color: var(--bg-secondary) !important;
    border: 1px solid var(--border-color) !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;
    box-shadow: none !important;
  }

  ms-zero-state .promo-card:hover {
    transform: translateY(-4px) !important;
    border-color: var(--accent-primary) !important;
    box-shadow: 0 4px 15px var(--shadow-color) !important;
  }

  /* --- KHUNG NHẬP LIỆU PROMPT --- */
  ms-prompt-input-wrapper .prompt-input-wrapper {
    background-color: var(--bg-secondary) !important;
    border: 1px solid var(--border-color) !important;
    border-radius: 24px !important; /* Bo tròn hơn */
    transition: border-color 0.3s ease, box-shadow 0.3s ease !important;
  }

  ms-prompt-input-wrapper .prompt-input-wrapper:focus-within {
    border-color: var(--accent-primary) !important;
    box-shadow: 0 0 10px var(--shadow-color) !important;
  }

  ms-chunk-input textarea {
    color: var(--text-primary) !important;
  }

  /* Nút Run */
  run-button button.run-button {
    background-color: var(--accent-primary) !important;
    color: var(--bg-primary) !important;
    border-radius: 16px !important;
    transition: background-color 0.3s ease, transform 0.2s ease !important;
  }

  run-button button.run-button:hover:not([disabled]) {
    background-color: #a6c8ff !important;
    transform: scale(1.05) !important;
  }

  run-button button.run-button.disabled {
    background-color: var(--bg-tertiary) !important;
    color: var(--text-secondary) !important;
  }
  
  /* Nút Thêm file */
  ms-add-chunk-menu button {
      color: var(--accent-primary) !important;
  }
  
  ms-add-chunk-menu button:hover {
      background-color: var(--bg-tertiary) !important;
  }

  /* --- PANEL CÀI ĐẶT BÊN PHẢI --- */
  ms-right-side-panel .content-container,
  ms-run-settings {
    background-color: var(--bg-secondary) !important;
    border-left: 1px solid var(--border-color) !important;
  }
  
  ms-run-settings h2, ms-run-settings h3, ms-run-settings p {
    color: var(--text-primary) !important;
  }

  /* Thanh trượt (Slider) */
  .mdc-slider__track--active_fill {
    border-color: var(--accent-primary) !important;
  }
  .mdc-slider__thumb-knob {
    background-color: var(--accent-primary) !important;
    border-color: var(--accent-primary) !important;
  }
  
  /* Nút bật/tắt (Toggle) */
  .mdc-switch--selected .mdc-switch__track::after {
    background: var(--accent-primary) !important;
  }
  .mdc-switch--selected .mdc-switch__handle::after {
    background: var(--text-primary) !important;
  }
}
